<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{Box,Check,Clock3,GitCommit,Play,RefreshCw,RotateCcw,Rocket,ShieldCheck}from'lucide-vue-next';import{useAuthStore}from'@/stores/useAuthStore';import{releaseStatusLabel,stageProgress}from'@/features/releases/releasesModel';type Stage={id:string;name:string;status:string;duration:string;message:string};type Release={id:string;application:string;version:string;previousVersion:string;environment:string;status:string;progress:number;operator:string;startedAt:string;strategy:string;approval:string;ticketId:string;stages:Stage[]};type Artifact={id:string;application:string;version:string;commit:string;size:string;createdAt:string;security:string};type Summary={today:number;running:number;success:number;failed:number;successRate:number};const auth=useAuthStore(),releases=ref<Release[]>([]),artifacts=ref<Artifact[]>([]),summary=ref<Summary>(),selected=ref<Release>(),tab=ref<'releases'|'artifacts'>('releases'),loading=ref(false);const headers=computed(()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'}));async function load(){loading.value=true;[summary.value,releases.value,artifacts.value]=await Promise.all(['summary','','artifacts'].map(x=>fetch('/api/v1/releases'+(x?'/'+x:''),{headers:headers.value}).then(r=>r.json())));loading.value=false}async function start(){await fetch('/api/v1/releases',{method:'POST',headers:headers.value,body:JSON.stringify({application:'订单服务',version:'v2.8.0',environment:'staging'})});await load()}async function rollback(){if(!selected.value)return;await fetch(`/api/v1/releases/${selected.value.id}/rollback`,{method:'POST',headers:headers.value});await load();selected.value=releases.value.find(x=>x.id===selected.value?.id)}onMounted(load)</script>
<template><section class="releases-page"><header class="releases-heading"><div><span>CONTINUOUS DELIVERY CONTROL</span><h1>发布管理中心</h1><p>制品、门禁、发布与回滚全链路控制</p></div><div><button @click="load"><RefreshCw :class="{spin:loading}"/>刷新</button><button class="primary" @click="start"><Rocket/>创建发布</button></div></header><div class="release-summary"><article><Rocket/><span>今日发布<strong>{{summary?.today}}</strong></span></article><article><Clock3/><span>发布中<strong>{{summary?.running}}</strong></span></article><article><Check/><span>成功<strong>{{summary?.success}}</strong></span></article><article><RotateCcw/><span>失败<strong>{{summary?.failed}}</strong></span></article><article><ShieldCheck/><span>成功率<strong>{{summary?.successRate}}%</strong></span></article></div><div class="release-workspace"><main><nav><button :class="{active:tab==='releases'}" @click="tab='releases'">发布流水线</button><button :class="{active:tab==='artifacts'}" @click="tab='artifacts'">制品仓库</button></nav><template v-if="tab==='releases'"><article v-for="r in releases" :key="r.id" class="release-card" :class="{selected:selected?.id===r.id}" @click="selected=r"><header><div><small>{{r.id}} · {{r.environment}}</small><h3>{{r.application}} <b>{{r.version}}</b></h3><span>{{r.strategy}} · {{r.operator}} · {{r.startedAt}}</span></div><em :data-status="r.status">{{releaseStatusLabel(r.status)}}</em></header><div class="pipeline"><div v-for="(s,i) in r.stages" :key="s.id" :data-status="s.status"><i><Check v-if="s.status==='success'"/><Play v-else-if="s.status==='running'"/></i><span>{{s.name}}<small>{{s.duration||s.message}}</small></span><b v-if="i<r.stages.length-1"></b></div></div><footer><div><i :style="{width:r.progress+'%'}"></i></div><span>{{r.progress}}%</span></footer></article></template><template v-else><article v-for="a in artifacts" :key="a.id" class="artifact-row"><Box/><div><strong>{{a.application}}:{{a.version}}</strong><span><GitCommit/>{{a.commit}} · {{a.size}}</span></div><time>{{a.createdAt}}</time><b><ShieldCheck/>安全扫描通过</b></article></template></main><aside class="release-detail"><template v-if="selected"><span>RELEASE DETAIL</span><h2>{{selected.application}} {{selected.version}}</h2><div class="release-gate"><ShieldCheck/><div><strong>发布门禁已通过</strong><span>审批、扫描、变更窗口校验完成</span></div></div><dl><div><dt>目标环境</dt><dd>{{selected.environment}}</dd></div><div><dt>发布策略</dt><dd>{{selected.strategy}}</dd></div><div><dt>关联工单</dt><dd>{{selected.ticketId||'—'}}</dd></div><div><dt>回滚版本</dt><dd>{{selected.previousVersion}}</dd></div></dl><h3>阶段日志</h3><div class="stage-logs"><article v-for="s in selected.stages" :key="s.id" :data-status="s.status"><i></i><div><strong>{{s.name}}</strong><span>{{s.message}} {{s.duration}}</span></div></article></div><footer><button :disabled="selected.status==='rolling-back'" @click="rollback"><RotateCcw/>回滚至 {{selected.previousVersion}}</button></footer></template><div v-else class="empty-release"><Rocket/><strong>选择发布流水线</strong><span>查看阶段状态与发布门禁</span></div></aside></div></section></template>
